query Query($inventoryNumber: String!, $locationId: String!) {
  inventory(where: {number:{_eq:$inventoryNumber} active:{_eq:true}}) {
    edges {
      node {

        location {
          id
          name
          locationType {
            id
            name

          }
        }
         id
        grossWeight
        netWeight
        tareWeight
        theoreticalWeight
        active
        barcode
        note
        trackingNumber
        customData
        quantity {
          value
          unitId
        }
        inventoryStatus {
          id
          active
         defective
      loaded
       mergePrevent
      movePrevent
      productionLoaded
      productionPrevent
      received
      shipPrevent
      shipped
      splitPrevent

          staged
          suspect
          usable
          color
          externalId

        }
        productStrategyProcessId
        lotId
        masterInventoryId
        packagingMaterialId
        receiptLineId
        supplierId
        weightUnitId
        workOrderId
        workOrderProcessId
    }
  }
}
  productionSetupMaterial(where:{inventory:{number:{_eq:$inventoryNumber}}}) {
    edges {
      node {
        id
        number
        productionSetup {
          id
          workcenter {
            name
          }
        }
      }
    }
  }
  location(where:{id:{_eq:$locationId}}) {
    edges {
      node {
        id
        name
        locationType {

          usable
        }
      }
    }
  }
  transactionType(where:{inventoryMove:{_eq:true}} first:1) {
    edges {
      node {
        id
      }
    }
  }
}

